-- 테이블 hipkc.current_stats 구조 내보내기
CREATE TABLE IF NOT EXISTS `current_stats` (
  `match_id` varchar(50) DEFAULT NULL,
  `psnId` varchar(50) DEFAULT NULL,
  `vs` varchar(50) DEFAULT NULL,
  `pts` int(11) DEFAULT NULL,
  `reb` int(11) DEFAULT NULL,
  `ast` int(11) DEFAULT NULL,
  `stl` int(11) DEFAULT NULL,
  `blk` int(11) unsigned DEFAULT NULL,
  `fls` int(11) DEFAULT NULL,
  `to` int(11) DEFAULT NULL,
  `fgm` int(11) DEFAULT NULL,
  `fga` int(11) DEFAULT NULL,
  `3pm` int(11) DEFAULT NULL,
  `3pa` int(11) DEFAULT NULL,
  KEY `match_id` (`match_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

